#include "fdtd-2d.h"

void init_array(
    int tmax,
    int nx,
    int ny,
    double ex[20][30],
    double ey[20][30],
    double hz[20][30],
    double _fict_[20]) {
    int i, j;

    for (i = 0; i < tmax; i++)
        _fict_[i] = (double)i;
    for (i = 0; i < nx; i++)
        for (j = 0; j < ny; j++) {
            ex[i][j] = ((double)i * (j + 1)) / nx;
            ey[i][j] = ((double)i * (j + 2)) / ny;
            hz[i][j] = ((double)i * (j + 3)) / nx;
        }
}

